import { Client, InMemoryTransport } from "@modelcontextprotocol/client";
import { createHevyClient } from "@hevy-mcp/hevy-client";
import { createHevyMcpServer } from "../server.js";

// Bug hunt sweep: every read tool, fed Hevy payloads where every field the
// OpenAPI spec marks nullable is null (plus empty strings / empty arrays),
// must return structuredContent that the server accepts against its own
// advertised outputSchema.

const nullSet = {
	index: 0,
	type: "normal",
	weight_kg: null,
	reps: null,
	distance_meters: null,
	duration_seconds: null,
	rpe: null,
	custom_metric: null,
};
const workout = {
	id: "w1",
	title: "Morning",
	routine_id: null,
	description: null,
	start_time: "2026-01-01T10:00:00Z",
	end_time: "2026-01-01T11:00:00Z",
	updated_at: "2026-01-01T11:00:00Z",
	created_at: "2026-01-01T11:00:00Z",
	exercises: [
		{
			index: 0,
			title: "Bench",
			notes: null,
			exercise_template_id: "T1",
			supersets_id: null,
			sets: [nullSet],
		},
	],
